inline json dump(DaxaRefinementReadback const& r,std::string const& prefix){json files=json::object();auto plane=[&](char const* name,auto const& values){std::string path=prefix+"."+name;write(path,values.data(),values.size()*sizeof(typename std::remove_reference_t<decltype(values)>::value_type));files[name]={{"path",path},{"sha256",daxa_preprocess_file_sha256(path)},{"elements",values.size()}};};
plane("disparity.f32",r.disparity);plane("confidence.f32",r.confidence);plane("validity.u32",r.validity);plane("depth.f32",r.depth);plane("metric_confidence.f32",r.metric_confidence);plane("metric_validity.u32",r.metric_validity);plane("provenance.u32",r.provenance);plane("source_ids.i64",r.source_ids);plane("age_ns.i64",r.age_ns);plane("prediction.f32",r.prediction);plane("prediction_validity.u32",r.prediction_validity);plane("lower.u32",r.lower);plane("upper.u32",r.upper);plane("reason.u32",r.reason);plane("method.u32",r.method);plane("winner.u32",r.winner);plane("best_cost.u32",r.best_cost);plane("second_cost.u32",r.second_cost);plane("supported_candidates.u32",r.supported_candidates);plane("evaluated_candidates.u32",r.evaluated_candidates);plane("subpixel_applied.u32",r.subpixel_applied);plane("raw_disparity.f32",r.raw_disparity);plane("raw_confidence.f32",r.raw_confidence);plane("raw_validity.u32",r.raw_validity);plane("census.u32",r.census);plane("census_validity.u32",r.census_validity);plane("luma.u32",r.luma);plane("support.u32",r.support);plane("rectified_left.u32",r.rectified_rgb[0]);plane("rectified_right.u32",r.rectified_rgb[1]);return files;}
inline json dump_completed(DaxaRefinementReadback const& r,std::string const& prefix){json files=json::object();auto plane=[&](char const* name,auto const& values){std::string path=prefix+"."+name;write(path,values.data(),values.size()*sizeof(typename std::remove_reference_t<decltype(values)>::value_type));files[name]={{"path",path},{"sha256",daxa_preprocess_file_sha256(path)},{"elements",values.size()}};};
plane("completed_disparity.f32",r.completed_disparity);plane("completed_depth.f32",r.completed_depth);plane("completed_confidence.f32",r.completed_confidence);plane("completed_validity.u32",r.completed_validity);plane("completed_provenance.u32",r.completed_provenance);plane("completed_source_ids.i64",r.completed_source_ids);plane("completed_age_ns.i64",r.completed_age_ns);return files;}
